            pillType: null,
            member: null,
            room: null,
            hover: false,
        };
    }

    private load(): void {
        let resourceId: string;
        let prefix: string;

        if (this.props.url) {
            if (this.props.inMessage) {
                const parts = parsePermalink(this.props.url);
                resourceId = parts.primaryEntityId; // The room/user ID
                prefix = parts.sigil; // The first character of prefix
            } else {
                resourceId = getPrimaryPermalinkEntity(this.props.url);
                prefix = resourceId ? resourceId[0] : undefined;
            }
        }

        const pillType =
            this.props.type ||
            {
                "@": PillType.UserMention,
                "#": PillType.RoomMention,
                "!": PillType.RoomMention,
            }[prefix];

        let member: RoomMember;
        let room: Room;
        switch (pillType) {
            case PillType.AtRoomMention:
                {
                    room = this.props.room;
                }
                break;
            case PillType.UserMention:
                {
                    const localMember = this.props.room?.getMember(resourceId);
                    member = localMember;
                    if (!localMember) {
                        member = new RoomMember(null, resourceId);
                        this.doProfileLookup(resourceId, member);
                    }
                }
                break;
            case PillType.RoomMention:
                {
                    const localRoom =
                        resourceId[0] === "#"
                            ? MatrixClientPeg.get()
                                  .getRooms()
                                  .find((r) => {
                                      return (
                                          r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId)
                                      );
                                  })
                            : MatrixClientPeg.get().getRoom(resourceId);
                    room = localRoom;
                    if (!localRoom) {
                        // TODO: This would require a new API to resolve a room alias to
                        // a room avatar and name.
                        // this.doRoomProfileLookup(resourceId, member);
                    }
                }
                break;
        }
        this.setState({ resourceId, pillType, member, room });
    }

    public componentDidMount(): void {
        this.unmounted = false;
        this.matrixClient = MatrixClientPeg.get();
        this.load();
    }

    public componentDidUpdate(prevProps: Readonly<IProps>): void {
        if (objectHasDiff(this.props, prevProps)) {
            this.load();
        }
    }

    public componentWillUnmount(): void {
        this.unmounted = true;
    }

    private onMouseOver = (): void => {
        this.setState({
            hover: true,
        });
    };

    private onMouseLeave = (): void => {
        this.setState({
            hover: false,
        });
    };

    private doProfileLookup(userId: string, member: RoomMember): void {
        MatrixClientPeg.get()
            .getProfileInfo(userId)
            .then((resp) => {
                if (this.unmounted) {
                    return;
                }
                member.name = resp.displayname;
                member.rawDisplayName = resp.displayname;
                member.events.member = {
                    getContent: () => {
                        return { avatar_url: resp.avatar_url };
                    },
                    getDirectionalContent: function () {
                        return this.getContent();
                    },
                } as MatrixEvent;
                this.setState({ member });
            })
            .catch((err) => {
                logger.error("Could not retrieve profile data for " + userId + ":", err);
            });
    }

    private onUserPillClicked = (e: ButtonEvent): void => {
        e.preventDefault();
        dis.dispatch({
            action: Action.ViewUser,
            member: this.state.member,
        });
    };

    public render(): React.ReactNode {
        const resource = this.state.resourceId;

        let avatar = null;
        let linkText = resource;
        let pillClass;
        let userId;
        let href = this.props.url;
        let onClick;
        switch (this.state.pillType) {
            case PillType.AtRoomMention:
                {
                    const room = this.props.room;
                    if (room) {
                        linkText = "@room";
                        if (this.props.shouldShowPillAvatar) {
                            avatar = <RoomAvatar room={room} width={16} height={16} aria-hidden="true" />;
                        }
                        pillClass = "mx_AtRoomPill";
                    }
                }
                break;
            case PillType.UserMention:
                {
                    // If this user is not a member of this room, default to the empty member
                    const member = this.state.member;
                    if (member) {
                        userId = member.userId;
                        member.rawDisplayName = member.rawDisplayName || "";
                        linkText = member.rawDisplayName;
