import React, { useState } from "react";
import classNames from "classnames";
import { Room } from "matrix-js-sdk/src/models/room";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import MatrixClientContext from "../../../contexts/MatrixClientContext";
import Tooltip, { Alignment } from "./Tooltip";
import { usePermalink } from "../../../hooks/usePermalink";

export enum PillType {
    UserMention = "TYPE_USER_MENTION",
    RoomMention = "TYPE_ROOM_MENTION",
    AtRoomMention = "TYPE_AT_ROOM_MENTION", // '@room' mention
}

interface IProps {
    // The Type of this Pill. If url is given, this is auto-detected.
    type?: PillType;
    // The URL to pillify (no validation is done)
    url?: string;
    // Whether the pill is in a message
    inMessage?: boolean;
    // The room in which this pill is being rendered
    room?: Room;
    // Whether to include an avatar in the pill
    shouldShowPillAvatar?: boolean;
}

export function pillRoomNotifPos(text: string): number {
    return text.indexOf("@room");
}

export function pillRoomNotifLen(): number {
    return "@room".length;
}

export const Pill: React.FC<IProps> = ({ type, url, inMessage, room, shouldShowPillAvatar }) => {
    const [hover, setHover] = useState(false);
    const { avatar, onClick, resourceId, text, type: pillType } = usePermalink({ room, type, url });

    // Deliberately render nothing if the URL isn't recognised
    if (!pillType) return null;

    const classes = classNames("mx_Pill", {
        mx_AtRoomPill: pillType === PillType.AtRoomMention,
        mx_RoomPill: pillType === PillType.RoomMention,
        mx_SpacePill: pillType === "space",
        mx_UserPill: pillType === PillType.UserMention,
        mx_UserPill_me: pillType === PillType.UserMention && resourceId === MatrixClientPeg.get().getUserId(),
    });

    const inner = (
        <>
            {shouldShowPillAvatar ? avatar : null}
            <span className="mx_Pill_linkText">{text}</span>
            {hover && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null}
        </>
    );

    return (
        <bdi>
            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
                {inMessage && url ? (
                    <a
                        className={classes}
                        href={url}
                        onClick={onClick ?? undefined}
                        onMouseOver={() => setHover(true)}
                        onMouseLeave={() => setHover(false)}
                    >
                        {inner}
                    </a>
                ) : (
                    <span className={classes} onMouseOver={() => setHover(true)} onMouseLeave={() => setHover(false)}>
                        {inner}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
};

