Licensed under the Apache License, Version 2.0 (the "License");
you may not use this file except in compliance with the License.
You may obtain a copy of the License at

    http://www.apache.org/licenses/LICENSE-2.0

Unless required by applicable law or agreed to in writing, software
distributed under the License is distributed on an "AS IS" BASIS,
WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
See the License for the specific language governing permissions and
limitations under the License.
*/

import React, { ReactElement, useCallback, useEffect, useMemo, useState } from "react";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { logger } from "matrix-js-sdk/src/logger";

import { MatrixClientPeg } from "../MatrixClientPeg";
import { parsePermalink } from "../utils/permalinks/Permalinks";
import dis from "../dispatcher/dispatcher";
import { Action } from "../dispatcher/actions";
import RoomAvatar from "../components/views/avatars/RoomAvatar";
import MemberAvatar from "../components/views/avatars/MemberAvatar";
import { PillType } from "../components/views/elements/Pill";
import { ButtonEvent } from "../components/views/elements/AccessibleButton";

interface Args {
    room?: Room;
    type?: PillType;
    url?: string;
}

interface HookResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

export const usePermalink = ({ room, type: argType, url }: Args): HookResult => {
    let resourceId: string | null = null;
    if (url) {
        const parsed = parsePermalink(url);
        if (parsed?.primaryEntityId) resourceId = parsed.primaryEntityId;
    }
    const prefix = resourceId ? resourceId[0] : "";
    const type: PillType | null =
        argType ||
        ({ "@": PillType.UserMention, "#": PillType.RoomMention, "!": PillType.RoomMention } as Record<
            string,
            PillType
        >)[prefix] ||
        null;

    const initialMember = useMemo((): RoomMember | null => {
        if (type !== PillType.UserMention || !resourceId) return null;
        return room?.getMember(resourceId) ?? new RoomMember(null as any, resourceId);
    }, [type, resourceId, room]);

    const [lookedUp, setLookedUp] = useState<RoomMember | null>(null);

    useEffect(() => {
        setLookedUp(null);
        if (type !== PillType.UserMention || !resourceId) return;
        if (room?.getMember(resourceId)) return;
        let cancelled = false;
        MatrixClientPeg.get()
            .getProfileInfo(resourceId)
            .then((resp) => {
                if (cancelled) return;
                const m = new RoomMember(null as any, resourceId!);
                m.name = resp.displayname || resourceId!;
                m.rawDisplayName = resp.displayname || resourceId!;
                m.events.member = {
                    getContent: () => ({ avatar_url: resp.avatar_url }),
                    getDirectionalContent: function () {
                        return this.getContent();
                    },
                } as MatrixEvent;
                setLookedUp(m);
            })
            .catch((err) => {
                logger.error("Could not retrieve profile data for " + resourceId + ":", err);
            });
        return () => {
            cancelled = true;
        };
    }, [type, resourceId, room]);

    const member = lookedUp ?? initialMember;

    const targetRoom = useMemo((): Room | null => {
        if (type === PillType.AtRoomMention) return room ?? null;
        if (type !== PillType.RoomMention || !resourceId) return null;
        const cli = MatrixClientPeg.get();
        if (resourceId[0] === "#") {
            return (
                cli
                    .getRooms()
                    .find(
                        (r) => r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId!),
                    ) ?? null
            );
        }
        return cli.getRoom(resourceId) ?? null;
    }, [type, resourceId, room]);

    const onUserClick = useCallback(
        (e: ButtonEvent): void => {
            e.preventDefault();
            dis.dispatch({ action: Action.ViewUser, member });
        },
        [member],
    );

    let avatar: ReactElement | null = null;
    let text: string | null = null;
    let onClick: ((e: ButtonEvent) => void) | null = null;
    let resultType: PillType | "space" | null = type;

    switch (type) {
        case PillType.AtRoomMention:
            if (targetRoom) {
                text = "@room";
                avatar = <RoomAvatar room={targetRoom} width={16} height={16} aria-hidden="true" />;
            }
            break;
        case PillType.UserMention:
            if (member) {
                text = member.name || resourceId;
                avatar = <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />;
                onClick = onUserClick;
            }
            break;
        case PillType.RoomMention:
            if (targetRoom) {
                text = targetRoom.name || resourceId;
                avatar = <RoomAvatar room={targetRoom} width={16} height={16} aria-hidden="true" />;
                if (targetRoom.isSpaceRoom()) resultType = "space";
            } else {
                text = resourceId;
            }
            break;
    }

    return { avatar, text, onClick, resourceId, type: resultType };
};

