export const Pill: React.FC<IProps> = ({ type: propType, url, inMessage, room, shouldShowPillAvatar }) => {
    const [hover, setHover] = useState(false);
    const { avatar, onClick, resourceId, text, type } = usePermalink({ room, type: propType, url });

    if (!type || !text) return null;

    const classes = classNames("mx_Pill", {
        mx_AtRoomPill: type === PillType.AtRoomMention,
        mx_RoomPill: type === PillType.RoomMention,
        mx_SpacePill: type === "space",
        mx_UserPill: type === PillType.UserMention,
        mx_UserPill_me: type === PillType.UserMention && resourceId === MatrixClientPeg.get().getUserId(),
    });

    const onMouseOver = (): void => setHover(true);
    const onMouseLeave = (): void => setHover(false);
    const tip = hover && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;
    const content = (
        <>
            {shouldShowPillAvatar && avatar}
            <span className="mx_Pill_linkText">{text}</span>
            {tip}
        </>
    );

    return (
        <bdi>
            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
                {inMessage && url ? (
                    <a
                        className={classes}
                        href={url}
                        onClick={onClick ?? undefined}
                        onMouseOver={onMouseOver}
                        onMouseLeave={onMouseLeave}
                    >
                        {content}
                    </a>
                ) : (
                    <span className={classes} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
                        {content}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
};
