def get_abbrev_from_full_lang_name(input_lang_name: str, languages=None) -> str:
    """
    Return the three-character language code whose canonical or translated
    name matches the input (case- and accent-insensitive).

    :raises LanguageNoMatchError: when no language matches
    :raises LanguageMultipleMatchError: when more than one language matches
    """
    if languages is None:
        languages = get_languages()

    def normalize(s: str) -> str:
        return strip_accents(s).lower()

    target = normalize(input_lang_name)
    matches = []
    for language in languages.values():
        names = [language.name]
        translations = getattr(language, 'name_translated', None) or {}
        for translated_names in translations.values():
            names.extend(translated_names or [])
        if any(name and normalize(name) == target for name in names):
            matches.append(language.code)

    if len(matches) == 1:
        return matches[0]
    if not matches:
        raise LanguageNoMatchError(input_lang_name)
    raise LanguageMultipleMatchError(input_lang_name)


def autocomplete_languages(prefix: str):
    def normalize(s: str) -> str:
        return strip_accents(s).lower()

    prefix = normalize(prefix)
    user_lang = web.ctx.lang or 'en'
    for lang in get_languages().values():
        user_lang_name = safeget(lambda: lang['name_translated'][user_lang][0])
        if user_lang_name and normalize(user_lang_name).startswith(prefix):
            yield web.storage(
                key=lang.key,
                code=lang.code,
                name=user_lang_name,
            )
            continue

        lang_iso_code = safeget(lambda: lang['identifiers']['iso_639_1'][0])
        native_lang_name = safeget(lambda: lang['name_translated'][lang_iso_code][0])
        if native_lang_name and normalize(native_lang_name).startswith(prefix):
            yield web.storage(
                key=lang.key,
                code=lang.code,
                name=native_lang_name,
            )
            continue

        if normalize(lang.name).startswith(prefix):
            yield web.storage(
                key=lang.key,
                code=lang.code,
                name=lang.name,
            )
            continue


